<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import Icon from './Icon.vue';
import MoneyField from './MoneyField.vue';
import CountryFlag from './CountryFlag.vue';
import mchLogo from './assets/mch-logo.png';
import {warehouseApi} from './api';
import './style.css';
const vModalFocus={mounted(el){const previous=document.activeElement;el.setAttribute('tabindex','-1');const background=[...document.querySelectorAll('.wp-shell > :not(.wp-overlay)')];background.forEach(e=>e.inert=true);const overflow=document.body.style.overflow;document.body.style.overflow='hidden';el.focus();const trap=e=>{if(e.key!=='Tab')return;const items=[...el.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.getClientRects().length);if(!items.length){e.preventDefault();return;}if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement===el)){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&(document.activeElement===items.at(-1)||document.activeElement===el)){e.preventDefault();items[0].focus();}};el.addEventListener('keydown',trap);el._restore=()=>{background.forEach(e=>e.inert=false);document.body.style.overflow=overflow;el.removeEventListener('keydown',trap);if(previous?.isConnected)previous.focus();};},unmounted(el){el._restore?.();}};
const isPreview=import.meta.env.DEV;
const props=defineProps({warehouse:{type:String,default:''}});
const warehouse=props.warehouse||(location.pathname.startsWith('/warehouse-58nv1')?'58nv1':'singapore');
const isSG=warehouse==='singapore', title=isSG?'SINGAPORE':'58NV1', other=isSG?'58NV1':'SINGAPORE';
const portalUrl=isSG?'https://sale.halo.com.vn/warehouse-58nv1':'https://sing.halo.com.vn';
const profile=ref(null),booting=ref(true),busy=ref(false),error=ref(''),notice=ref(''),view=ref('home');
const email=ref(''),password=ref('');
const products=ref([]),batches=ref([]),documents=ref([]),history=ref([]),search=ref('');
function expire(message=''){profile.value=null;activeDoc.value=null;createOpen.value=false;productModal.value=false;accessTarget.value=null;linkTarget.value=null;productLinks.value=[];products.value=[];batches.value=[];documents.value=[];history.value=[];accessUsers.value=[];reportRows.value=[];notice.value='';if(message)error.value=message;}
const api=warehouseApi(warehouse,expire);
const loginPrefs=api.preferences(),remember=ref(loginPrefs.remember!==false);email.value=loginPrefs.email||'';
watch(remember,value=>api.rememberInfo(value,email.value));
onUnmounted(()=>api.dispose());
const canWrite=computed(()=>['operator','admin'].includes(profile.value?.role));
const nav=[['home','home','Tổng quan'],['products','box','Sản phẩm'],['stock','box','Tồn kho'],['documents','in','Nhập · Xuất'],['transfers','transfer','Chuyển kho'],['history','clock','Lịch sử'],['reports','chart','Báo cáo'],['access','shield','Quyền truy cập'],['links','transfer','Liên kết sản phẩm']];
const names={import:'Nhập kho',export:'Xuất kho',opening:'Tồn đầu kỳ',stocktake:'Kiểm kê',transfer:'Chuyển kho'};
const statuses={draft:'Bản nháp',confirmed:'Đã xác nhận',dispatched:'Đang vận chuyển',partial:'Nhận một phần',completed:'Đã đối soát',cancelled:'Đã huỷ'};
const fmt=n=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(Number(n)||0);
const dateOnly=s=>s?String(s).slice(0,10):'';
const pretty=s=>s?new Date(s).toLocaleDateString('vi-VN',{timeZone:profile.value?.timezone||'Asia/Singapore'}):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:isSG?'Asia/Singapore':'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const activeTransfers=computed(()=>documents.value.filter(d=>['dispatched','partial'].includes(d.status)));
const awaiting=computed(()=>activeTransfers.value.filter(d=>d.destination_code===warehouse));
const totalStock=computed(()=>products.value.reduce((s,p)=>s+p.stock,0));
const low=computed(()=>products.value.filter(p=>p.stock<=p.warning_stock));
const soon=computed(()=>batches.value.filter(b=>b.expiry_date&&dateOnly(b.expiry_date)>=today()&&new Date(b.expiry_date)-new Date(today())<=90*864e5));
const stockValue=computed(()=>batches.value.reduce((s,b)=>s+Number(b.import_cost||0)*b.current_quantity,0));
const filteredProducts=computed(()=>products.value.filter(p=>(p.sku+' '+p.name).toLowerCase().includes(search.value.toLowerCase())));
const shownDocs=computed(()=>documents.value.filter(d=>view.value==='transfers'?d.type==='transfer':d.type!=='transfer'));
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{return await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function refresh(){const [p,b,d,h]=await Promise.all([api.call('/products'),api.call('/batches'),api.call('/documents'),api.call('/history')]);products.value=p.products;batches.value=b.batches;documents.value=d.documents;history.value=h.movements;}
async function login(){await run(async()=>{profile.value=await api.login(email.value,password.value,remember.value);password.value='';await refresh();});}
async function logout(){await run(async()=>{await api.logout();expire();password.value='';});}
onMounted(async()=>{document.title=(isSG?'MCH':'HALO')+' · Kho '+title;if(api.hasSession()){try{profile.value=await api.call('/profile');await refresh();}catch(e){api.clear();profile.value=null;error.value=e.message;}}booting.value=false;});
watch(view,()=>{search.value='';error.value='';if(view.value==='access')run(loadAccess);if(view.value==='links')run(loadLinks);});

const createOpen=ref(false),step=ref(1),draft=ref({}),activeDoc=ref(null),action=ref(''),confirmation=ref(''),checked=ref(false),actionNote=ref(''),receiveQty=ref({}),actionRequest=ref('');
const selectedProduct=ref(''),selectedBatch=ref(''),quantity=ref(''),batchCode=ref(''),expiry=ref(''),mfg=ref(''),cost=ref('');
const productQuery=ref('');
const availableProducts=computed(()=>products.value.filter(p=>(p.sku+' '+p.name).toLowerCase().includes(productQuery.value.toLowerCase())));
const productBatches=computed(()=>batches.value.filter(b=>b.product_id===selectedProduct.value&&(draft.value.type==='stocktake'?b.status==='active':b.usable)));
const incoming=computed(()=>['import','opening'].includes(draft.value.type));
watch(selectedProduct,()=>{selectedBatch.value='';});
function start(type){if(!canWrite.value)return;draft.value={requestId:crypto.randomUUID(),type,currency:'VND',exchangeRate:1,counterparty:'',note:'',attachmentUrl:'',documentDate:today(),destination:isSG?'58nv1':'singapore',lines:[]};step.value=1;createOpen.value=true;error.value='';selectedProduct.value='';quantity.value='';productQuery.value='';}
function addLine(){error.value='';const p=products.value.find(p=>p.id===selectedProduct.value),b=batches.value.find(b=>b.id===selectedBatch.value);
  if(!p){error.value='Chọn sản phẩm trước.';return;}
  const qty=Number(quantity.value);if(quantity.value===''||!Number.isSafeInteger(qty)||qty<(draft.value.type==='stocktake'?0:1)){error.value='Nhập số lượng nguyên hợp lệ.';return;}
  if(!incoming.value&&!b){error.value='Chọn đúng lô cần xuất / kiểm kê.';return;}
  if(!incoming.value&&draft.value.type!=='stocktake'&&qty>b.current_quantity){error.value='Số lượng vượt tồn của lô đã chọn.';return;}
  if(incoming.value&&(!batchCode.value.trim()||!cost.value||!Number.isFinite(Number(cost.value))||Number(cost.value)<=0)){error.value='Nhập số lô và giá vốn lớn hơn 0.';return;}
  const item={productId:p.id,sku:p.sku,name:p.name,packageSize:p.package_size,quantity:qty,batchId:b?.id,batchCode:incoming.value?batchCode.value.trim():b.batch_code,expiryDate:incoming.value?expiry.value||null:dateOnly(b.expiry_date)||null,manufactureDate:incoming.value?mfg.value||null:dateOnly(b.manufacture_date)||null,unitCostMinor:incoming.value?Math.round(Number(cost.value)*(draft.value.currency==='SGD'?100:1)):undefined,expectedQuantity:b?.current_quantity};
  if(draft.value.lines.some(l=>l.productId===item.productId&&l.batchCode===item.batchCode)){error.value='Lô này đã có trong phiếu. Xoá dòng cũ nếu cần nhập lại.';return;}
  draft.value.lines.push(item);quantity.value='';batchCode.value='';expiry.value='';mfg.value='';cost.value='';selectedBatch.value='';notice.value='Đã thêm dòng hàng vào bản nháp.';
}
function reviewDraft(){error.value='';if(!draft.value.counterparty.trim()||!draft.value.lines.length||!draft.value.documentDate){error.value='Cần người giao / nhận / lý do, ngày phiếu và ít nhất một dòng hàng.';return;}step.value=2;}
async function saveDraft(){await run(async()=>{const {id}=await api.call('/documents',draft.value);createOpen.value=false;await refresh();await openDoc(id);notice.value='Đã lưu bản nháp. Tồn kho chưa thay đổi.';});}
async function openDoc(id){error.value='';action.value='';activeDoc.value=await api.call(`/documents/${id}`);}
function beginAction(type){action.value=type;confirmation.value='';checked.value=false;actionNote.value='';receiveQty.value={};actionRequest.value=crypto.randomUUID();error.value='';}
const actionLabel=computed(()=>({confirm:activeDoc.value?.type==='transfer'?'Xác nhận đã gửi hàng':activeDoc.value?.type==='stocktake'?'Chốt kiểm kê':'Xác nhận '+(names[activeDoc.value?.type]||'phiếu').toLowerCase(),receive:'Xác nhận số đã nhận',reconcile:'Chốt phần thiếu / hỏng',cancel:'Huỷ bản nháp'}[action.value]||''));
const receiveLines=computed(()=>activeDoc.value?.lines.filter(l=>l.quantity-l.received-l.reconciled>0)||[]);
const actionReady=computed(()=>confirmation.value===title&&checked.value&&(!['receive','reconcile','cancel'].includes(action.value)||actionNote.value.trim())&&(!['receive','reconcile'].includes(action.value)||receiveLines.value.some(l=>Number(receiveQty.value[l.id])>0)));
async function submitAction(){if(!actionReady.value)return;await run(async()=>{const body={revision:activeDoc.value.revision,confirmation:confirmation.value,checked:checked.value,note:actionNote.value,requestId:actionRequest.value};if(['receive','reconcile'].includes(action.value))body.lines=receiveLines.value.filter(l=>Number(receiveQty.value[l.id])>0).map(l=>({lineId:l.id,quantity:Number(receiveQty.value[l.id])}));await api.call(`/documents/${activeDoc.value.id}/${action.value}`,body);notice.value='Đã ghi nhận. Tồn và lịch sử đã được cập nhật.';await openDoc(activeDoc.value.id);await refresh();});}
const productModal=ref(false),newProduct=ref({});
function startProduct(){newProduct.value={sku:'',name:'',packageSize:'',unit:'Hộp',image:''};productModal.value=true;error.value='';}
async function saveProduct(){await run(async()=>{await api.call('/products',newProduct.value);await refresh();productModal.value=false;notice.value='Đã tạo sản phẩm. Chưa phát sinh tồn kho.';});}
const reportFrom=ref(today()),reportTo=ref(today()),reportRows=ref([]);
async function loadReport(){await run(async()=>{reportRows.value=(await api.call(`/report?from=${reportFrom.value}&to=${reportTo.value}`)).rows;});}
const accessUsers=ref([]),accessTarget=ref(null),accessRole=ref('viewer'),accessCost=ref(false),accessConfirmation=ref(''),accessChecked=ref(false);
async function loadAccess(){accessUsers.value=(await api.call('/access')).users;}
function editAccess(user){accessTarget.value=user;accessRole.value=user.role||'none';accessCost.value=!!user.see_cost;accessConfirmation.value='';accessChecked.value=false;error.value='';}
async function saveAccess(){await run(async()=>{await api.call('/access',{userId:accessTarget.value.id,role:accessRole.value,seeCost:accessCost.value,confirmation:accessConfirmation.value,checked:accessChecked.value});await loadAccess();accessTarget.value=null;notice.value='Đã cập nhật quyền tại '+title+'. Người dùng cần đăng nhập lại kho này.';});}
const productLinks=ref([]),linkTarget=ref(null),linkConfirmation=ref(''),linkChecked=ref(false);
async function loadLinks(){productLinks.value=(await api.call('/product-links')).links;}
function reviewLink(link){linkTarget.value=link;linkConfirmation.value='';linkChecked.value=false;error.value='';}
async function approveLink(){await run(async()=>{const l=linkTarget.value;await api.call('/product-links',{sourceId:l.source_id,targetId:l.target_id,sourceSignature:l.source_signature,targetSignature:l.target_signature,confirmation:linkConfirmation.value,checked:linkChecked.value});await loadLinks();linkTarget.value=null;notice.value='Đã xác nhận liên kết hai chiều cho '+l.sku+'. Không thay đổi tên, quy cách hay tồn của hai kho.';});}
const loading=ref(false);
async function reload(){if(loading.value)return;loading.value=true;await run(async()=>{await refresh();if(view.value==='links')await loadLinks();if(view.value==='access')await loadAccess();});loading.value=false;}
</script>

<template>
<div class="wp-shell" :class="isSG?'wp-sg':'wp-nv'">
  <CountryFlag v-if="isSG" singapore class="wp-country-backdrop" preserveAspectRatio="xMidYMid slice" aria-hidden="true"/>
  <div v-if="isPreview" class="wp-preview-badge">BẢN THỬ · DỮ LIỆU GIẢ LẬP</div>
  <div v-if="booting" class="wp-boot" role="status">Đang kiểm tra phiên kho {{ title }}…</div>
  <div v-else-if="!profile" class="wp-login">
    <section class="wp-login-story">
      <a class="wp-brand" href="/"><img v-if="isSG" :src="mchLogo" alt="MCH Global Pte. Ltd." class="wp-mch-logo"><template v-else><span class="wp-brand-mark">H</span> HALO<span class="wp-brand-sub">WAREHOUSE</span></template></a>
      <div class="wp-story-copy"><span class="wp-eyebrow">MỘT KHO. MỘT PHIÊN. ĐÚNG TRÁCH NHIỆM.</span><h1>Rõ từng lô hàng.<br>Chắc từng lần chuyển.</h1><p>Không gian vận hành riêng của kho {{ title }}.<br>Mỗi lần nhập, xuất và nhận hàng đều có dấu vết.</p></div>
      <svg class="wp-warehouse-art" viewBox="0 0 620 250" fill="none" aria-hidden="true"><path d="m60 115 235-95 255 95v125H60V115Z" stroke="currentColor" stroke-width="1.5"/><path d="M60 115h490M112 239V145h100v94m40 0V145h100v94m40 0V145h100v94M295 20v95M84 105l211-61 233 62M133 166h59m-59 20h59m-59 20h59m-59 20h59m81-60h59m-59 20h59m-59 20h59m-59 20h59" stroke="currentColor"/><path d="M423 217v-43h44v43h-44Zm22-43v43m-22-25h44M24 240h566" stroke="currentColor" stroke-width="1.5"/><circle cx="550" cy="48" r="22" stroke="currentColor"/><path d="m541 48 7 7 11-15" stroke="currentColor" stroke-width="2"/></svg>
      <div class="wp-login-foot"><Icon name="shield"/> Phiên đăng nhập được giới hạn theo từng kho</div>
    </section>
    <section class="wp-login-form"><div class="wp-login-card"><span class="wp-location"><CountryFlag :singapore="isSG" class="wp-flag"/> {{isSG?'SG · SINGAPORE':'VN · 58NV1'}}</span><h2>Đăng nhập kho {{title}}</h2><p class="wp-muted">Dùng tài khoản được cấp quyền tại kho này.</p>
      <div class="wp-context-note"><Icon name="alert"/><span>Bạn đang vào <strong>{{title}}</strong>. Đăng nhập tại đây sẽ tự đăng xuất kho {{other}} trong cùng trình duyệt.</span></div>
      <form @submit.prevent="login"><label>Email<input v-model="email" type="email" autocomplete="username" required placeholder="Email của bạn" :disabled="busy"></label><label>Mật khẩu<input v-model="password" type="password" autocomplete="current-password" required placeholder="Nhập mật khẩu" :disabled="busy"></label><label class="wp-remember"><input v-model="remember" type="checkbox" :disabled="busy">Nhớ thông tin đăng nhập</label><p v-if="error" class="wp-error" role="alert">{{error}}</p><button class="wp-primary wp-wide" :disabled="busy">{{busy?'Đang kiểm tra…':'Đăng nhập vào '+title}}<Icon name="arrow"/></button></form>
      <div class="wp-login-other">Bạn cần thao tác tại kho {{other}}?<a :href="portalUrl">Mở cổng kho {{other}} <span>↗</span></a></div>
      <p class="wp-small wp-muted">Nhớ email và phiên tối đa 8 giờ. App không lưu mật khẩu. Bỏ tích khi dùng máy chung.</p>
    </div></section>
  </div>

  <template v-else>
    <aside class="wp-sidebar"><a class="wp-brand" href="/"><img v-if="isSG" :src="mchLogo" alt="MCH Global Pte. Ltd." class="wp-mch-logo"><template v-else><span class="wp-brand-mark">H</span> HALO<span class="wp-brand-sub">OPERATIONS</span></template></a><div class="wp-side-location"><span class="wp-eyebrow">KHO ĐANG ĐĂNG NHẬP</span><strong>{{title}}</strong><span>{{isSG?'Singapore · UTC+8':'Việt Nam · UTC+7'}}</span></div>
      <nav aria-label="Chức năng kho"><button v-for="[id,icon,label] in nav.filter(n=>!['access','links'].includes(n[0])||profile.role==='admin')" :key="id" @click="view=id" :class="{active:view===id}" :aria-current="view===id?'page':undefined"><Icon :name="icon"/>{{label}}<b v-if="id==='transfers'&&awaiting.length">{{awaiting.length}}</b></button></nav>
      <div class="wp-sidebar-bottom"><Icon name="shield"/><p>Chỉ thao tác tại <strong>{{title}}</strong>.<br>Kho nhận tự kiểm đếm và xác nhận.</p><a :href="portalUrl">Mở cổng {{other}} ↗</a></div>
    </aside>
    <div class="wp-workspace"><header class="wp-topbar"><div class="wp-live-warehouse"><img v-if="isSG" :src="mchLogo" alt="MCH Global" class="wp-header-logo"><CountryFlag :singapore="isSG" class="wp-country-flag"/><strong>KHO {{title}}</strong><span class="wp-session-label"><i/> Phiên kho riêng</span></div><div class="wp-user"><span>{{profile.fullName}}<small>{{profile.role==='admin'?'Quản trị kho':profile.role==='operator'?'Nhân viên kho':'Chỉ xem'}}</small></span><button class="wp-icon-btn" @click="logout" :disabled="busy" title="Đăng xuất kho này" aria-label="Đăng xuất kho này"><Icon name="logout"/></button></div></header>
      <main class="wp-main">
        <div class="wp-page-heading"><div><span class="wp-eyebrow">HALO / KHO {{title}}</span><h1>{{nav.find(n=>n[0]===view)?.[2]}}</h1><p class="wp-muted">{{view==='home'?'Nhịp vận hành hôm nay, trong một góc nhìn.':view==='transfers'?'Gửi đúng kho. Nhận đúng số thực tế.':`Dữ liệu riêng của kho ${title}.`}}</p></div><button class="wp-secondary" @click="reload" :disabled="busy||loading"><Icon name="clock"/>{{loading?'Đang tải…':'Làm mới'}}</button></div>
        <p v-if="error&&!activeDoc&&!createOpen&&!productModal" class="wp-error" role="alert">{{error}}</p><p v-if="notice" class="wp-notice" role="status">{{notice}}<button @click="notice=''" aria-label="Đóng thông báo">×</button></p>

        <template v-if="view==='home'">
          <section class="wp-overview-banner"><div><span class="wp-eyebrow">ĐÚNG KHO TRƯỚC KHI XÁC NHẬN</span><h2>Bạn đang vận hành kho {{title}}.</h2><p>Gửi hàng tại kho đi. Nhận hàng tại kho đến.<br>Mỗi bước là một xác nhận độc lập.</p></div><div class="wp-banner-seal"><Icon name="shield"/><span>ĐÚNG KHO<br>ĐÚNG SỐ LƯỢNG</span></div></section>
          <div class="wp-stats"><article><span><Icon name="box"/> Tồn có thể xuất</span><strong>{{fmt(totalStock)}}</strong><small>Đơn vị sản phẩm · {{products.filter(p=>p.stock>0).length}} mã còn hàng</small></article><article><span><Icon name="transfer"/> Chờ kho này nhận</span><strong>{{fmt(awaiting.length)}}<em>phiếu</em></strong><small>Cần kiểm đếm thực tế trước khi nhận</small></article><article><span><Icon name="clock"/> Lô sắp hết hạn</span><strong>{{fmt(soon.length)}}<em>lô</em></strong><small>Hạn sử dụng trong 90 ngày tới</small></article><article><span><Icon name="chart"/> {{profile.seeCost?'Giá trị tồn vật lý':'Mã đạt ngưỡng tồn thấp'}}</span><strong>{{fmt(profile.seeCost?stockValue:low.length)}}<em>{{profile.seeCost?'₫':'mã'}}</em></strong><small>{{profile.seeCost?'Giá vốn lô · quy đổi VND':'Bao gồm các mã chưa có hàng'}}</small></article></div>
          <div class="wp-section-title"><h2>Bắt đầu công việc</h2><span class="wp-muted wp-small">{{canWrite?'Mọi thao tác đều có bước xem lại':'Tài khoản hiện tại chỉ được xem'}}</span></div>
          <div class="wp-quick-actions"><button :disabled="!canWrite||!profile.seeCost" @click="start('import')"><span class="wp-action-icon"><Icon name="in"/></span><strong>Nhập hàng</strong><small>Nhận hàng vào {{title}}</small><Icon name="arrow"/></button><button :disabled="!canWrite" @click="start('export')"><span class="wp-action-icon"><Icon name="out"/></span><strong>Xuất hàng</strong><small>Giao hàng từ {{title}}</small><Icon name="arrow"/></button><button :disabled="!canWrite" @click="start('transfer')"><span class="wp-action-icon"><Icon name="transfer"/></span><strong>Chuyển sang {{other}}</strong><small>Kho {{other}} xác nhận nhận riêng</small><Icon name="arrow"/></button></div>
          <section class="wp-panel wp-awaiting"><div class="wp-section-title"><h2>Hàng chờ bạn nhận</h2><button class="wp-text-button" @click="view='transfers'">Xem phiếu chuyển →</button></div><div v-if="!awaiting.length" class="wp-empty"><Icon name="check"/><h3>Chưa có hàng chờ nhận</h3><p>Phiếu sẽ xuất hiện khi kho {{other}} xác nhận đã gửi.</p></div><button class="wp-document-row" v-for="d in awaiting" :key="d.id" @click="run(()=>openDoc(d.id))"><Icon name="transfer"/><div><strong>{{d.code}}</strong><small>{{d.warehouse_code==='singapore'?'Singapore':'58NV1'}} → {{title}}</small></div><span>{{fmt(d.quantity-d.received-d.reconciled)}} còn chờ</span><Icon name="arrow"/></button></section>
        </template>

        <template v-if="view==='products'||view==='stock'">
          <div class="wp-toolbar"><label class="wp-search"><Icon name="search"/><input v-model="search" aria-label="Tìm sản phẩm" placeholder="Tìm theo mã hoặc tên sản phẩm…"></label><button v-if="view==='products'&&canWrite" class="wp-primary" @click="startProduct"><Icon name="plus"/>Thêm sản phẩm</button><template v-if="view==='stock'&&profile.role==='admin'"><button class="wp-secondary" @click="start('opening')" :disabled="!profile.seeCost">Nhập tồn đầu</button><button class="wp-primary" @click="start('stocktake')">Kiểm kê</button></template></div>
          <section class="wp-panel"><div class="wp-table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Quy cách</th><th>Có thể xuất</th><th>Tồn vật lý</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="p in filteredProducts" :key="p.id"><td><div class="wp-product-cell"><img v-if="p.main_image_url" :src="p.main_image_url" alt="" loading="lazy" referrerpolicy="no-referrer"><span v-else class="wp-image-placeholder"><Icon name="box"/></span><div><small>{{p.sku}}</small><strong>{{p.name}}</strong></div></div></td><td>{{p.package_size||'Chưa xác nhận'}}</td><td class="wp-number">{{fmt(p.stock)}} <small>{{p.unit}}</small></td><td>{{fmt(p.physical_stock)}}</td><td><span class="wp-tag" :class="p.stock===0?'wp-tag-muted':p.stock<=p.warning_stock?'wp-tag-warn':''">{{p.stock===0?'Chưa có hàng':p.stock<=p.warning_stock?'Tồn thấp':'Còn hàng'}}</span></td></tr></tbody></table></div><div v-if="!filteredProducts.length" class="wp-empty"><Icon name="box"/><h3>{{search?'Không tìm thấy sản phẩm':'Danh mục đang trống'}}</h3><p>{{search?'Thử mã hoặc tên khác.':'Thêm sản phẩm trước, sau đó ghi nhận tồn đầu kỳ hoặc phiếu nhập.'}}</p></div></section>
          <section v-if="view==='stock'&&batches.length" class="wp-panel wp-mt"><div class="wp-section-title"><h2>Chi tiết theo lô</h2><span class="wp-small wp-muted">Sắp xếp theo hạn dùng</span></div><div class="wp-table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Số lô</th><th>Hạn dùng</th><th>Số lượng</th><th>Trạng thái</th><th v-if="profile.seeCost">Giá vốn VND</th></tr></thead><tbody><tr v-for="b in batches.filter(b=>(b.sku+' '+b.name).toLowerCase().includes(search.toLowerCase()))" :key="b.id"><td>{{b.sku}} · {{b.name}}</td><td>{{b.batch_code}}</td><td>{{pretty(b.expiry_date)}}</td><td class="wp-number">{{fmt(b.current_quantity)}}</td><td><span class="wp-tag" :class="!b.usable?'wp-tag-warn':''">{{b.usable?'Có thể xuất':'Không được xuất'}}</span></td><td v-if="profile.seeCost">{{b.import_cost===null?'Thiếu giá vốn':fmt(b.import_cost)}}</td></tr></tbody></table></div></section>
        </template>

        <template v-if="view==='documents'||view==='transfers'">
          <div v-if="view==='transfers'" class="wp-transfer-route"><div :class="isSG?'wp-route-sg':'wp-route-vn'"><small>KHO ĐANG ĐĂNG NHẬP</small><strong>{{title}}</strong></div><Icon name="transfer"/><div :class="isSG?'wp-route-vn':'wp-route-sg'"><small>KHO ĐỐI ỨNG</small><strong>{{other}}</strong></div><p>Hàng đang vận chuyển chưa thuộc tồn có thể xuất của kho nhận.</p></div>
          <div class="wp-toolbar"><span class="wp-muted">{{shownDocs.length}} phiếu gần nhất</span><div v-if="canWrite" class="wp-button-group"><template v-if="view==='documents'"><button v-if="profile.seeCost" class="wp-secondary" @click="start('import')"><Icon name="in"/>Nhập hàng</button><button class="wp-primary" @click="start('export')"><Icon name="out"/>Xuất hàng</button></template><button v-else class="wp-primary" @click="start('transfer')"><Icon name="plus"/>Chuyển sang {{other}}</button></div></div>
          <section class="wp-panel"><div class="wp-table-wrap"><table><thead><tr><th>Mã phiếu</th><th>Nghiệp vụ / hướng chuyển</th><th>Ngày phiếu</th><th>Số lượng</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="d in shownDocs" :key="d.id"><td><button class="wp-text-button" @click="run(()=>openDoc(d.id))">{{d.code}}</button><small class="wp-block">{{d.counterparty}}</small></td><td>{{d.type==='transfer'?`${d.warehouse_code==='singapore'?'Singapore':'58NV1'} → ${d.destination_code==='singapore'?'Singapore':'58NV1'}`:names[d.type]}}</td><td>{{pretty(d.document_date)}}</td><td>{{fmt(d.quantity)}}<small class="wp-block" v-if="d.type==='transfer'">Nhận {{fmt(d.received)}} · xử lý {{fmt(d.reconciled)}}</small></td><td><span class="wp-tag" :class="'wp-status-'+d.status">{{statuses[d.status]}}</span></td><td><button class="wp-icon-btn" @click="run(()=>openDoc(d.id))" :aria-label="'Xem phiếu '+d.code"><Icon name="arrow"/></button></td></tr></tbody></table></div><div v-if="!shownDocs.length" class="wp-empty"><Icon :name="view==='transfers'?'transfer':'in'"/><h3>Chưa có phiếu {{view==='transfers'?'chuyển kho':'nhập · xuất'}}</h3><p>Bắt đầu bằng bản nháp. Tồn chỉ thay đổi sau khi xác nhận.</p></div></section>
        </template>

        <section v-if="view==='history'" class="wp-panel"><div class="wp-table-wrap"><table><thead><tr><th>Thời gian</th><th>Sản phẩm / lô</th><th>Thay đổi</th><th>Người thực hiện</th><th>Tham chiếu</th></tr></thead><tbody><tr v-for="m in history" :key="m.id"><td>{{new Date(m.created_at).toLocaleString('vi-VN',{timeZone:profile.timezone})}}</td><td>{{m.sku}}<small class="wp-block">{{m.batch_code}}</small></td><td class="wp-number" :class="m.quantity<0?'wp-negative':'wp-positive'">{{m.quantity>0?'+':''}}{{fmt(m.quantity)}}</td><td>{{m.full_name||'Hệ thống'}}</td><td>{{m.note}}</td></tr></tbody></table></div><div v-if="!history.length" class="wp-empty"><Icon name="clock"/><h3>Chưa có biến động kho</h3><p>Mỗi lần chốt phiếu sẽ tạo một dòng lịch sử tại đây.</p></div></section>

        <template v-if="view==='reports'"><div class="wp-toolbar wp-align-end"><label>Từ ngày<input type="date" v-model="reportFrom"></label><label>Đến ngày<input type="date" v-model="reportTo"></label><button class="wp-primary" @click="loadReport" :disabled="busy">Xem báo cáo</button><button class="wp-secondary" @click="run(()=>api.download(reportFrom,reportTo))" :disabled="busy">Tải Excel</button></div><p class="wp-small wp-muted">Kỳ báo cáo theo thời điểm xác nhận trên hệ thống và múi giờ của kho {{title}}.</p><section class="wp-panel"><div class="wp-table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Tồn đầu</th><th>Nhập</th><th>Xuất</th><th>Điều chỉnh</th><th>Tồn cuối</th></tr></thead><tbody><tr v-for="r in reportRows" :key="r.sku"><td>{{r.sku}}<small class="wp-block">{{r.name}}</small></td><td>{{fmt(r.opening)}}</td><td>{{fmt(r.incoming)}}</td><td>{{fmt(r.outgoing)}}</td><td>{{fmt(r.adjustment)}}</td><td class="wp-number">{{fmt(r.closing)}}</td></tr></tbody></table></div><div v-if="!reportRows.length" class="wp-empty"><Icon name="chart"/><h3>Chọn kỳ cần đối soát</h3><p>Tồn đầu + nhập − xuất + điều chỉnh = tồn cuối.</p></div></section></template>
        <template v-if="view==='access'&&profile.role==='admin'"><div class="wp-context-note"><Icon name="shield"/><span>Quyền tại <strong>{{title}}</strong> được cấp riêng. Thay đổi ở đây không cấp quyền tại {{other}}. Người dùng phải đăng nhập lại sau khi quyền thay đổi.</span></div><section class="wp-panel"><div class="wp-table-wrap"><table><thead><tr><th>Nhân sự</th><th>Quyền tại {{title}}</th><th>Giá vốn</th><th></th></tr></thead><tbody><tr v-for="u in accessUsers" :key="u.id"><td><strong>{{u.full_name}}</strong><small class="wp-block">{{u.email}}</small></td><td>{{({admin:'Quản trị kho',operator:'Nhân viên kho',viewer:'Chỉ xem'})[u.role]||'Chưa được cấp'}}</td><td>{{u.see_cost?'Được xem':'Ẩn'}}</td><td><button class="wp-secondary" @click="editAccess(u)" :disabled="u.id===profile.userId">{{u.id===profile.userId?'Phiên của bạn':'Sửa quyền'}}</button></td></tr></tbody></table></div></section></template>
        <template v-if="view==='links'&&profile.role==='admin'"><div class="wp-context-note"><Icon name="alert"/><span>Đối chiếu <strong>cùng sản phẩm, cùng hàm lượng và quy cách</strong> ở hai kho. Liên kết chỉ dùng cho chuyển kho hai chiều, không sửa tên hay tồn. Nếu thông tin thay đổi, cần xác nhận lại.</span></div><section class="wp-panel"><div class="wp-table-wrap"><table><thead><tr><th>Mã</th><th>Tại {{title}}</th><th>Tại {{other}}</th><th>Đối chiếu</th></tr></thead><tbody><tr v-for="l in productLinks" :key="l.source_id"><td><strong>{{l.sku}}</strong></td><td>{{l.source_name}}<small class="wp-block">{{l.source_pack||'Chưa có quy cách'}}</small></td><td>{{l.target_name}}<small class="wp-block">{{l.target_pack||'Chưa có quy cách'}}</small></td><td><span v-if="l.compatible||l.approved" class="wp-tag">{{l.approved?'Quản trị đã xác nhận':'Thông tin trùng khớp'}}</span><button v-else class="wp-secondary" @click="reviewLink(l)">Đối chiếu & liên kết</button></td></tr></tbody></table></div><div v-if="!productLinks.length" class="wp-empty"><Icon name="transfer"/><h3>Chưa có mã chung cần đối chiếu</h3><p>Khi kho nhận chưa có mã, hệ thống tạo danh mục theo phiếu gửi; chưa cộng tồn.</p></div></section></template>
        <footer class="wp-footer">HALO WAREHOUSE <span>Kho {{title}} · {{isSG?'Asia/Singapore':'Asia/Ho_Chi_Minh'}} · Phiên độc lập</span></footer>
      </main>
    </div>
  </template>

  <div v-if="createOpen" class="wp-overlay"><section class="wp-modal wp-modal-wide" v-modal-focus role="dialog" aria-modal="true" :aria-label="names[draft.type]" tabindex="-1"><div class="wp-modal-header"><div><span class="wp-eyebrow">KHO {{title}} · {{step===1?'BƯỚC 1/2':'BƯỚC 2/2'}}</span><h2>{{names[draft.type]}}{{draft.type==='transfer'?' → '+other:''}}</h2></div><button class="wp-icon-btn" @click="createOpen=false" :disabled="busy" aria-label="Đóng bản nháp"><Icon name="close"/></button></div><div class="wp-modal-body">
    <div class="wp-context-note"><Icon name="shield"/><span>{{step===1?'Nhập thông tin rồi xem lại toàn bộ phiếu.':'Kiểm tra từng dòng trước khi lưu.'}} <strong>Chưa thay đổi tồn kho.</strong></span></div>
    <template v-if="step===1"><div class="wp-form-grid"><label>{{draft.type==='import'?'Nhà cung cấp':draft.type==='stocktake'?'Lý do / đợt kiểm kê':draft.type==='transfer'?'Người / đơn vị vận chuyển':'Người nhận / lý do'}}<input v-model="draft.counterparty" maxlength="300" placeholder="Nhập đầy đủ để đối soát"></label><label>Ngày phiếu<input v-model="draft.documentDate" type="date" :max="today()"></label><template v-if="incoming"><label>Đồng tiền<select v-model="draft.currency" :disabled="draft.lines.length>0" @change="draft.exchangeRate=draft.currency==='VND'?1:''"><option>VND</option><option>SGD</option></select></label><label v-if="draft.currency==='SGD'">Tỷ giá 1 SGD = ? VND<input v-model="draft.exchangeRate" inputmode="decimal" type="number" min="1" step="0.000001"></label></template><label class="wp-full">Ghi chú<textarea v-model="draft.note" rows="2" maxlength="2000" placeholder="Thông tin giao nhận hoặc lưu ý cho kho"></textarea></label><label class="wp-full">Link chứng từ (nếu có)<input v-model="draft.attachmentUrl" type="url" placeholder="https://…"></label></div>
    <fieldset class="wp-line-builder"><legend>Thêm dòng hàng</legend><label>Tìm sản phẩm<input v-model="productQuery" placeholder="Mã hoặc tên sản phẩm"></label><label>Sản phẩm<select v-model="selectedProduct"><option value="">Chọn sản phẩm tại {{title}}</option><option v-for="p in availableProducts" :key="p.id" :value="p.id">{{p.sku}} · {{p.name}} · {{p.package_size||'Chưa rõ quy cách'}}</option></select></label><div class="wp-form-grid"><template v-if="!incoming"><label class="wp-full">Lô hàng<select v-model="selectedBatch"><option value="">Chọn lô đã kiểm tra</option><option v-for="b in productBatches" :value="b.id" :key="b.id">{{b.batch_code}} · HSD {{pretty(b.expiry_date)}} · Tồn {{fmt(b.current_quantity)}}</option></select></label></template><template v-else><label>Số lô<input v-model="batchCode" placeholder="Đúng mã in trên sản phẩm"></label><label>Giá nhập / đơn vị ({{draft.currency}})<MoneyField v-model="cost" :currency="draft.currency"/></label><label>Ngày sản xuất (nếu có)<input v-model="mfg" type="date"></label><label>Hạn dùng (nếu có)<input v-model="expiry" type="date"></label></template><label>{{draft.type==='stocktake'?'Số đếm thực tế':'Số lượng'}}<input v-model="quantity" type="number" inputmode="numeric" :min="draft.type==='stocktake'?0:1" step="1" placeholder="Nhập số đã kiểm đếm"></label><button class="wp-secondary wp-align-self-end" @click="addLine"><Icon name="plus"/>Thêm dòng</button></div></fieldset></template>
    <div class="wp-review-route" v-if="draft.type==='transfer'"><strong>{{title}}</strong><Icon name="arrow"/><strong>{{other}}</strong><small>Kho nhận phải đăng nhập riêng để nhận hàng.</small></div>
    <div v-if="step===2" class="wp-review-meta"><p><small>NGƯỜI GIAO / NHẬN / LÝ DO</small><strong>{{draft.counterparty}}</strong></p><p><small>NGÀY PHIẾU</small><strong>{{pretty(draft.documentDate)}}</strong></p><p v-if="draft.note"><small>GHI CHÚ</small><span>{{draft.note}}</span></p></div>
    <div class="wp-table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Lô / HSD</th><th>{{draft.type==='stocktake'?'Thực đếm':'Số lượng'}}</th><th v-if="incoming">Giá / đơn vị</th><th v-if="step===1"></th></tr></thead><tbody><tr v-for="(l,index) in draft.lines" :key="l.productId+l.batchCode"><td data-label="Sản phẩm">{{l.sku}}<strong class="wp-block">{{l.name}}</strong><small>{{l.packageSize}}</small></td><td data-label="Lô / Hạn dùng">{{l.batchCode}}<small class="wp-block">{{pretty(l.expiryDate)}}</small></td><td class="wp-number" data-label="Số lượng">{{fmt(l.quantity)}}<small v-if="draft.type==='stocktake'" class="wp-block">Hệ thống {{l.expectedQuantity}}</small></td><td v-if="incoming" data-label="Giá / đơn vị">{{fmt(l.unitCostMinor/(draft.currency==='SGD'?100:1))}} {{draft.currency}}</td><td v-if="step===1"><button class="wp-icon-btn" @click="draft.lines.splice(index,1)" :aria-label="'Xoá dòng '+l.sku"><Icon name="close"/></button></td></tr></tbody></table></div><p v-if="!draft.lines.length" class="wp-muted wp-small">Chưa thêm dòng hàng.</p><p v-if="error" class="wp-error" role="alert">{{error}}</p>
    </div><div class="wp-modal-footer"><button class="wp-secondary" @click="step===2?step=1:createOpen=false" :disabled="busy">{{step===2?'Quay lại sửa':'Đóng'}}</button><button class="wp-primary" v-if="step===1" @click="reviewDraft">Xem lại phiếu <Icon name="arrow"/></button><button class="wp-primary" v-else @click="saveDraft" :disabled="busy">{{busy?'Đang lưu…':'Lưu bản nháp'}}</button></div></section></div>

  <div v-if="activeDoc" class="wp-overlay"><section class="wp-modal wp-modal-wide" v-modal-focus role="dialog" aria-modal="true" aria-label="Chi tiết và xác nhận phiếu"><div class="wp-modal-header"><div><span class="wp-eyebrow">ĐANG ĐĂNG NHẬP KHO {{title}}</span><h2>{{activeDoc.code}}</h2><span class="wp-tag" :class="'wp-status-'+activeDoc.status">{{statuses[activeDoc.status]}}</span></div><button class="wp-icon-btn" :disabled="busy" @click="activeDoc=null;action='';error=''" aria-label="Đóng chi tiết phiếu"><Icon name="close"/></button></div><div class="wp-modal-body"><div class="wp-review-route" v-if="activeDoc.type==='transfer'"><strong>{{activeDoc.warehouse_code==='singapore'?'SINGAPORE':'58NV1'}}</strong><Icon name="arrow"/><strong>{{activeDoc.destination_code==='singapore'?'SINGAPORE':'58NV1'}}</strong></div><div class="wp-review-meta"><p><small>NGHIỆP VỤ</small><strong>{{names[activeDoc.type]}}</strong></p><p><small>NGƯỜI GIAO / NHẬN / LÝ DO</small><strong>{{activeDoc.counterparty}}</strong></p><p><small>NGÀY PHIẾU</small><span>{{pretty(activeDoc.document_date)}}</span></p><p v-if="activeDoc.note"><small>GHI CHÚ</small><span>{{activeDoc.note}}</span></p><p v-if="activeDoc.attachment_url"><small>CHỨNG TỪ</small><a :href="activeDoc.attachment_url" target="_blank" rel="noopener noreferrer">Mở chứng từ ↗</a></p></div>
    <div class="wp-table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Lô / HSD</th><th>Số lượng</th><template v-if="activeDoc.type==='transfer'&&! ['draft','cancelled'].includes(activeDoc.status)"><th>Đã nhận</th><th>Thiếu / hỏng đã xử lý</th><th>Còn chờ</th></template><th v-if="profile.seeCost">Giá vốn VND</th></tr></thead><tbody><tr v-for="l in activeDoc.lines" :key="l.id"><td data-label="Sản phẩm">{{l.sku}}<strong class="wp-block">{{l.name}}</strong><small>{{l.package_size}}</small></td><td data-label="Lô / Hạn dùng">{{l.batch_code}}<small class="wp-block">{{pretty(l.expiry_date)}}</small></td><td class="wp-number" data-label="Số lượng">{{fmt(l.quantity)}}</td><template v-if="activeDoc.type==='transfer'&&! ['draft','cancelled'].includes(activeDoc.status)"><td data-label="Đã nhận">{{fmt(l.received)}}</td><td data-label="Thiếu / hỏng đã xử lý">{{fmt(l.reconciled)}}</td><td data-label="Còn đang vận chuyển">{{fmt(l.quantity-l.received-l.reconciled)}}</td></template><td v-if="profile.seeCost" data-label="Giá vốn VND">{{l.cost_vnd===null?'Chưa có':fmt(l.cost_vnd)}}</td></tr></tbody></table></div>
    <div v-if="action" class="wp-confirm-box"><span class="wp-eyebrow">BƯỚC XÁC NHẬN TẠI {{title}}</span><h3>{{actionLabel}}</h3><p v-if="action==='confirm'&&activeDoc.type==='transfer'">Thao tác này giảm tồn kho {{title}}. Kho {{other}} chưa được cộng tồn cho đến khi xác nhận thực nhận.</p><p v-else-if="action==='receive'">Chỉ nhập số hàng đã kiểm đếm và có thể nhập kho. Để trống dòng chưa nhận. Phần còn lại tiếp tục nằm ở hàng đang vận chuyển.</p><p v-else-if="action==='reconcile'" class="wp-negative">Số lượng xử lý thiếu / hỏng sẽ rời hàng đang vận chuyển và không được cộng vào tồn. Hàng trả về cần phiếu chuyển ngược riêng.</p><p v-else-if="action==='confirm'">Hãy đối chiếu sản phẩm, số lô, hạn dùng và số lượng. Xác nhận sẽ thay đổi tồn kho {{title}}.</p>
      <div v-if="['receive','reconcile'].includes(action)" class="wp-receive-lines"><label v-for="l in receiveLines" :key="l.id"><span><strong>{{l.sku}} · {{l.batch_code}}</strong><small>Còn chờ {{fmt(l.quantity-l.received-l.reconciled)}}</small></span><input v-model="receiveQty[l.id]" type="number" inputmode="numeric" min="1" :max="l.quantity-l.received-l.reconciled" step="1" :aria-label="'Số '+(action==='receive'?'thực nhận ':'thiếu hỏng ')+l.sku" placeholder="Nhập số thực tế"></label></div>
      <label v-if="['receive','reconcile','cancel'].includes(action)">Lý do / ghi chú kiểm đếm<textarea v-model="actionNote" rows="2" placeholder="Ghi rõ kết quả đối chiếu" maxlength="1000"></textarea></label><label class="wp-check"><input type="checkbox" v-model="checked"><span>Tôi đã kiểm tra phiếu và xác nhận đang thao tác tại <strong>KHO {{title}}</strong>.</span></label><label>Nhập <strong>{{title}}</strong> để xác nhận<input v-model="confirmation" :placeholder="title" autocomplete="off" spellcheck="false" @paste.prevent></label><button class="wp-primary wp-wide" :disabled="!actionReady||busy" @click="submitAction">{{busy?'Đang ghi nhận…':actionLabel+' tại '+title}}</button><button class="wp-text-button wp-mt" :disabled="busy" @click="action='';error=''">Quay lại kiểm tra</button>
    </div>
    <p v-if="error" class="wp-error" role="alert">{{error}}</p><section v-if="activeDoc.receipts.length" class="wp-mt"><h3>Lịch sử nhận và đối soát</h3><div v-for="r in activeDoc.receipts" :key="r.id" class="wp-receipt"><strong>{{r.type==='receive'?'Nhận hàng':'Xử lý chênh lệch'}} · {{r.full_name}}</strong><small>{{pretty(r.created_at)}}</small><p>{{r.note}}</p></div></section>
    </div><div v-if="!action&&canWrite" class="wp-modal-footer"><template v-if="activeDoc.status==='draft'&&activeDoc.warehouse_code===warehouse"><button class="wp-secondary" @click="beginAction('cancel')">Huỷ bản nháp</button><button class="wp-primary" @click="beginAction('confirm')">Kiểm tra & xác nhận <Icon name="arrow"/></button></template><template v-else-if="['dispatched','partial'].includes(activeDoc.status)&&activeDoc.destination_code===warehouse"><button v-if="profile.role==='admin'" class="wp-secondary" @click="beginAction('reconcile')">Xử lý thiếu / hỏng</button><button class="wp-primary" @click="beginAction('receive')">Kiểm đếm & nhận hàng <Icon name="in"/></button></template><p v-else class="wp-small wp-muted">{{activeDoc.type==='transfer'&&activeDoc.warehouse_code===warehouse?'Kho nhận phải đăng nhập tại cổng riêng để kiểm đếm và nhận hàng.':'Phiếu đã được ghi nhận, không xác nhận lại.'}}</p></div></section></div>

  <div v-if="linkTarget" class="wp-overlay"><section class="wp-modal" v-modal-focus role="dialog" aria-modal="true" aria-label="Đối chiếu sản phẩm hai kho"><div class="wp-modal-header"><div><span class="wp-eyebrow">QUẢN TRỊ ĐỐI CHIẾU · {{title}}</span><h2>Liên kết {{linkTarget.sku}}</h2></div><button class="wp-icon-btn" :disabled="busy" @click="linkTarget=null" aria-label="Đóng"><Icon name="close"/></button></div><div class="wp-modal-body"><div class="wp-review-meta"><p><small>KHO {{title}}</small><strong>{{linkTarget.source_name}}</strong><span>{{linkTarget.source_pack||'Chưa có quy cách'}}</span></p><p><small>KHO {{other}}</small><strong>{{linkTarget.target_name}}</strong><span>{{linkTarget.target_pack||'Chưa có quy cách'}}</span></p></div><p class="wp-small wp-muted">Chỉ xác nhận khi đã đối chiếu bao bì / thông số thực tế. Liên kết áp dụng cho cả hai chiều chuyển kho.</p><label class="wp-check"><input type="checkbox" v-model="linkChecked"><span>Tôi xác nhận đây là <strong>cùng một sản phẩm và quy cách</strong>, dù cách ghi tên khác nhau.</span></label><label>Nhập {{title}} để xác nhận<input v-model="linkConfirmation" :placeholder="title" autocomplete="off"></label><p v-if="error" class="wp-error" role="alert">{{error}}</p></div><div class="wp-modal-footer"><button class="wp-secondary" :disabled="busy" @click="linkTarget=null">Quay lại</button><button class="wp-primary" @click="approveLink" :disabled="busy||!linkChecked||linkConfirmation!==title">Xác nhận cùng sản phẩm</button></div></section></div>
  <div v-if="accessTarget" class="wp-overlay"><section class="wp-modal" v-modal-focus role="dialog" aria-modal="true" aria-label="Cấp quyền kho"><div class="wp-modal-header"><div><span class="wp-eyebrow">CHỈ ÁP DỤNG TẠI {{title}}</span><h2>Quyền của {{accessTarget.full_name}}</h2></div><button class="wp-icon-btn" :disabled="busy" @click="accessTarget=null" aria-label="Đóng"><Icon name="close"/></button></div><div class="wp-modal-body"><label>Quyền tại kho {{title}}<select v-model="accessRole"><option value="none">Thu hồi quyền</option><option value="viewer">Chỉ xem</option><option value="operator">Nhân viên kho · lập và xác nhận phiếu</option><option value="admin">Quản trị kho · kiểm kê và xử lý chênh lệch</option></select></label><label class="wp-check"><input type="checkbox" v-model="accessCost"><span>Cho phép xem và nhập giá vốn</span></label><label class="wp-check"><input type="checkbox" v-model="accessChecked"><span>Tôi xác nhận quyền này chỉ áp dụng tại <strong>{{title}}</strong>.</span></label><label>Nhập {{title}} để xác nhận<input v-model="accessConfirmation" :placeholder="title" autocomplete="off"></label><p v-if="error" class="wp-error" role="alert">{{error}}</p></div><div class="wp-modal-footer"><button class="wp-secondary" :disabled="busy" @click="accessTarget=null">Đóng</button><button class="wp-primary" @click="saveAccess" :disabled="busy||!accessChecked||accessConfirmation!==title">Lưu quyền tại {{title}}</button></div></section></div>
  <div v-if="productModal" class="wp-overlay"><form class="wp-modal" v-modal-focus @submit.prevent="saveProduct" role="dialog" aria-modal="true" aria-label="Thêm sản phẩm"><div class="wp-modal-header"><div><span class="wp-eyebrow">DANH MỤC KHO {{title}}</span><h2>Thêm sản phẩm</h2></div><button type="button" class="wp-icon-btn" @click="productModal=false" aria-label="Đóng"><Icon name="close"/></button></div><div class="wp-modal-body"><label>Mã sản phẩm<input v-model="newProduct.sku" required maxlength="60" placeholder="Ví dụ HC_10"></label><label>Tên sản phẩm<input v-model="newProduct.name" required maxlength="300"></label><div class="wp-form-grid"><label>Quy cách<input v-model="newProduct.packageSize" required placeholder="Ví dụ 200 viên"></label><label>Đơn vị<input v-model="newProduct.unit" required placeholder="Hộp / lọ / chai"></label></div><label>Link ảnh HTTPS (nếu có)<input v-model="newProduct.image" type="url" placeholder="https://…"></label><p class="wp-small wp-muted">Tạo danh mục không làm tăng tồn. Giá nhập được ghi trên từng phiếu và lô hàng.</p><p v-if="error" class="wp-error" role="alert">{{error}}</p></div><div class="wp-modal-footer"><button type="button" class="wp-secondary" @click="productModal=false">Đóng</button><button class="wp-primary" :disabled="busy">{{busy?'Đang lưu…':'Tạo tại '+title}}</button></div></form></div>
</div>
</template>
